# ============================================================
# Paper outputs for the Slack Monte Carlo simulation
# ============================================================
#
# Usage:
#   Rscript paper_results.R
# or:
#   Rscript paper_results.R path/to/results
#
# The script expects these files generated by simulation.py:
#   full_graphs_results_df.csv
#   full_mean_results.csv
#   full_mc_results_df.csv
#
# Outputs are written to results/paper_outputs by default.
# ============================================================

rm(list = ls())

required_packages <- c(
  "readr",
  "dplyr",
  "ggplot2",
  "stringr",
  "knitr",
  "patchwork"
)

missing_packages <- required_packages[
  !vapply(required_packages, requireNamespace, logical(1), quietly = TRUE)
]

if (length(missing_packages) > 0) {
  stop(
    "Missing R packages: ",
    paste(missing_packages, collapse = ", "),
    "\nInstall them with:\n",
    "install.packages(c(",
    paste(sprintf('"%s"', missing_packages), collapse = ", "),
    "))"
  )
}

library(readr)
library(dplyr)
library(ggplot2)
library(stringr)
library(knitr)
library(patchwork)

args <- commandArgs(trailingOnly = TRUE)
base_dir <- if (length(args) >= 1) args[[1]] else "results"

out_dir <- file.path(base_dir, "paper_outputs")
dir.create(out_dir, recursive = TRUE, showWarnings = FALSE)

graphs_path <- file.path(base_dir, "full_graphs_results_df.csv")
means_path  <- file.path(base_dir, "full_mean_results.csv")
mc_path     <- file.path(base_dir, "full_mc_results_df.csv")

required_files <- c(graphs_path, means_path, mc_path)
missing_files <- required_files[!file.exists(required_files)]

if (length(missing_files) > 0) {
  stop(
    "Required simulation output files not found:\n",
    paste(missing_files, collapse = "\n"),
    "\nRun simulation.py first."
  )
}

graphs <- read_csv(graphs_path, show_col_types = FALSE)
means  <- read_csv(means_path, show_col_types = FALSE)
mc     <- read_csv(mc_path, show_col_types = FALSE)

if (!"M_N_scenario" %in% names(graphs)) {
  graphs <- graphs %>%
    mutate(M_N_scenario = paste0("(", M, ",", N, ")"))
}

dist_order <- c(
  "gaussian",
  "student_t",
  "power_law_5_0",
  "power_law_3_0",
  "power_law_2_0",
  "power_law_1_5",
  "power_law_1_2"
)

dist_labels <- c(
  "gaussian"      = "Gaussian",
  "student_t"     = "Student-t",
  "power_law_5_0" = "Pareto alpha = 5.0",
  "power_law_3_0" = "Pareto alpha = 3.0",
  "power_law_2_0" = "Pareto alpha = 2.0",
  "power_law_1_5" = "Pareto alpha = 1.5",
  "power_law_1_2" = "Pareto alpha = 1.2"
)

graphs <- graphs %>%
  mutate(
    dist = factor(dist, levels = dist_order),
    dist_label = unname(dist_labels[as.character(dist)]),
    M_N_scenario = str_replace_all(M_N_scenario, " ", "")
  )

means <- means %>%
  mutate(
    M_N_scenario = str_replace_all(M_N_scenario, " ", "")
  )

mc <- mc %>%
  mutate(
    M_N_scenario = str_replace_all(M_N_scenario, " ", "")
  )


# ============================================================
# Table 2 in the manuscript:
# balanced scenario (M,N)=(100,100), theta=0.7
# ============================================================

table2 <- graphs %>%
  filter(
    theta == 0.7,
    M_N_scenario == "(100,100)"
  ) %>%
  group_by(dist, dist_label) %>%
  summarise(
    mean_min_slack_weighted =
      mean(min_slack_weighted, na.rm = TRUE),
    sd_min_slack_weighted =
      sd(min_slack_weighted, na.rm = TRUE),
    mean_frac_pivotal_pct =
      100 * mean(frac_slack_weighted_lt_one, na.rm = TRUE),
    mean_gini_slack_weighted =
      mean(gini_slack_weighted, na.rm = TRUE),
    n_replications = n(),
    .groups = "drop"
  ) %>%
  arrange(dist)

write_csv(
  table2,
  file.path(out_dir, "table2_balanced_theta07.csv")
)

sink(file.path(out_dir, "table2_balanced_theta07.tex"))
print(
  kable(
    table2 %>%
      select(
        Distribution = dist_label,
        `Mean x_min` = mean_min_slack_weighted,
        `SD x_min` = sd_min_slack_weighted,
        `Mean 100 p_piv` = mean_frac_pivotal_pct,
        `Mean G(x)` = mean_gini_slack_weighted
      ),
    format = "latex",
    booktabs = TRUE,
    digits = 4,
    caption = paste0(
      "Monte Carlo summary for the balanced scenario ",
      "$(M,N)=(100,100)$ and $\\theta=0.7$."
    )
  )
)
sink()


# ============================================================
# Figure 2 in the manuscript:
# distributional sensitivity at theta=0.7
# ============================================================

clean_labels <- c(
  "gaussian"       = "Gaussian",
  "student_t"      = "Student-t",
  "power_law_5_0"  = "Pareto (α = 5.0)",
  "power_law_3_0"  = "Pareto (α = 3.0)",
  "power_law_2_0"  = "Pareto (α = 2.0)",
  "power_law_1_5"  = "Pareto (α = 1.5)",
  "power_law_1_2"  = "Pareto (α = 1.2)"
)

m_vals <- seq(140, 60, by = -10)
n_vals <- seq(60, 140, by = 10)
all_scenarios <- paste0("(", m_vals, ",", n_vals, ")")
theta_focus <- 0.7

plot_df <- means %>%
  filter(
    theta == theta_focus,
    dist %in% dist_order,
    M_N_scenario %in% all_scenarios
  ) %>%
  mutate(
    dist = factor(dist, levels = dist_order),
    M_N_scenario = factor(M_N_scenario, levels = all_scenarios)
  )

create_transition_subplot <- function(
    metric,
    ylabel_text,
    ylim = NULL,
    add_threshold = TRUE
) {
  p <- ggplot(
    plot_df,
    aes(
      x = dist,
      y = .data[[metric]],
      color = M_N_scenario,
      group = M_N_scenario
    )
  ) +
    geom_line(linewidth = 0.8) +
    geom_point(size = 1.6) +
    scale_x_discrete(
      limits = rev(dist_order),
      labels = clean_labels
    ) +
    scale_color_viridis_d(option = "plasma", end = 0.9) +
    labs(
      title = paste0("θ = ", theta_focus),
      x = "Distributional regime (heavier-tailed to lighter-tailed)",
      y = ylabel_text,
      color = "(M, N)"
    ) +
    theme_minimal(base_size = 11) +
    theme(
      panel.border = element_rect(
        color = "black",
        fill = NA,
        linewidth = 0.5
      ),
      legend.position = "right",
      axis.text.x = element_text(angle = 45, hjust = 1)
    )

  if (add_threshold) {
    p <- p +
      geom_hline(
        yintercept = 1,
        linetype = "dashed",
        color = "gray50"
      )
  }

  if (!is.null(ylim)) {
    p <- p + coord_cartesian(ylim = ylim)
  }

  p
}

panel_a <- create_transition_subplot(
  metric = "min_slack_weighted",
  ylabel_text = expression(paste("Mean minimum Slack"^W)),
  add_threshold = TRUE
)

panel_b <- create_transition_subplot(
  metric = "frac_slack_weighted_lt_one",
  ylabel_text = expression(
    paste("Mean fraction with Slack"^W, " < 1")
  ),
  ylim = c(0, 0.2),
  add_threshold = FALSE
)

figure2 <- panel_a + panel_b + plot_layout(widths = c(1, 1))

ggsave(
  filename = file.path(
    out_dir,
    "figure2_distributional_sensitivity_theta07.png"
  ),
  plot = figure2,
  width = 14,
  height = 5,
  dpi = 300,
  bg = "white"
)


# ============================================================
# Table 3 in the manuscript:
# paired directional Monte Carlo comparison at theta=0.7,
# averaged across the nine (M,N) configurations
# ============================================================

table3_min <- mc %>%
  filter(
    theta == 0.7,
    metric == "min_slack_weighted"
  ) %>%
  group_by(alternative_dist) %>%
  summarise(
    min_mean_difference = mean(mean_difference, na.rm = TRUE),
    min_share_more_fragile =
      mean(share_alt_more_fragile, na.rm = TRUE),
    min_median_p_mc = median(mc_pvalue, na.rm = TRUE),
    .groups = "drop"
  )

table3_piv <- mc %>%
  filter(
    theta == 0.7,
    metric == "frac_slack_weighted_lt_one"
  ) %>%
  group_by(alternative_dist) %>%
  summarise(
    pivotal_mean_pct = 100 * mean(alternative_mean, na.rm = TRUE),
    pivotal_share_more_fragile =
      mean(share_alt_more_fragile, na.rm = TRUE),
    pivotal_median_p_mc = median(mc_pvalue, na.rm = TRUE),
    .groups = "drop"
  )

table3 <- left_join(
  table3_min,
  table3_piv,
  by = "alternative_dist"
) %>%
  mutate(
    distribution = unname(dist_labels[alternative_dist]),
    order = match(alternative_dist, dist_order)
  ) %>%
  arrange(order) %>%
  select(
    distribution,
    min_mean_difference,
    min_share_more_fragile,
    min_median_p_mc,
    pivotal_mean_pct,
    pivotal_share_more_fragile,
    pivotal_median_p_mc
  )

write_csv(
  table3,
  file.path(out_dir, "table3_paired_monte_carlo_theta07.csv")
)

sink(file.path(out_dir, "table3_paired_monte_carlo_theta07.tex"))
print(
  kable(
    table3,
    format = "latex",
    booktabs = TRUE,
    digits = 4,
    caption = paste0(
      "Paired Monte Carlo comparison against the Gaussian benchmark ",
      "at $\\theta=0.7$, averaged across the nine $(M,N)$ configurations."
    )
  )
)
sink()

cat(
  "\nPaper outputs created in:\n",
  normalizePath(out_dir, mustWork = FALSE),
  "\n"
)
